return [{
  json: {
    q: '삼성전자',
    naver_display: 20,
    naver_sort: 'date',
    serper_gl: 'kr',
    serper_hl: 'ko',
    serper_num: 20,
    serper_tbs: 'qdr:d'
  }
}];

const naver = $('T2. HTTP Request - Naver News').first().json || {};
const serper = $('T3. HTTP Request - Serper News').first().json || {};

function stripHtml(v) {
  return String(v || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}
function normUrl(u) {
  return String(u || '')
    .replace(/#.*$/, '')
    .replace(/[?&](utm_[^=&]+|nclick)=[^&]*/gi, '')
    .replace(/[?&]$/, '')
    .replace(/\/$/, '');
}
function dateValue(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? Date.now() : d.getTime();
}

// 주가/증시 시황 기사 하드 제외(제목 기준) — "투자·협력" 같은 사업 기사는 남기고,
// 단순 주가 등락/증시 코멘트류만 제외한다.
const STOCK_EXCLUDE = [
  '주가', '주식', '증시', '코스피', '코스닥', '목표주가', '투자의견', '매수의견', '매도의견',
  '상한가', '하한가', '52주', '시가총액', '순매수', '순매도', '개미', '반등', '폭락', '급락',
  '급등', '약세', '강세', '거래량', '신저가', '신고가',
  // 2026-07-30: 실사용 중 이 목록을 하나도 안 건드리는 투자자 대상 기사(목표가 조정, 주주환원
  // 정책, 실적발표 콘퍼런스콜 등)가 그대로 섞여 들어오는 게 확인돼 추가. '실적'/'실적 발표' 자체는
  // 제외하지 않는다 — 이건 정상적인 경영 성과 뉴스라 남겨야 한다는 게 확인됨.
  '목표가', '주주환원', '투심', '콘콜', '컨센서스', 'PER', 'PBR'
];
function isStockNoise(title) {
  const t = String(title || '');
  return STOCK_EXCLUDE.some(term => t.includes(term));
}

const naverArticles = (Array.isArray(naver.items) ? naver.items : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.originallink || r.link || '').trim(),
  source: 'Naver News',
  published_at_raw: r.pubDate || null,
  summary: stripHtml(r.description).slice(0, 300),
  image_url: null
}));

const serperArticles = (Array.isArray(serper.news) ? serper.news : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.link || '').trim(),
  source: r.source || 'Serper News',
  published_at_raw: r.date || null,
  summary: stripHtml(r.snippet).slice(0, 300),
  image_url: String(r.imageUrl || '').trim() || null
}));

const all = [...naverArticles, ...serperArticles]
  .filter(a => a.title && a.url)
  .filter(a => !isStockNoise(a.title));

// 완전 중복(URL·제목 동일)만 1차로 제거 — 서로 다른 매체의 같은 사건 판단은
// 문자열 유사도로는 신뢰도가 낮아(금액 표기가 매체마다 "2000억달러"/"292조원"으로
// 다르게 쓰이는 등) AI에게 맡긴다.
const exactMap = new Map();
for (const a of all) {
  const key = normUrl(a.url) + '|' + a.title.replace(/\s+/g, '');
  if (!exactMap.has(key)) exactMap.set(key, a);
}
const items = [...exactMap.values()]
  .sort((a, b) => dateValue(b.published_at_raw) - dateValue(a.published_at_raw));

if (!items.length) {
  throw new Error('삼성전자 관련 최근 기사를 하나도 찾지 못했습니다(주식 시황 기사 제외 후 0건). Naver/Serper 응답을 확인하세요.');
}

const listText = items.map((a, i) => `${i}. ${a.title} — ${a.summary.slice(0, 80)}`).join('\n');

const prompt = `아래는 오늘 "삼성전자" 검색으로 수집한 뉴스 기사 목록이다. 번호는 기사 인덱스(0부터 시작)다.

같은 사건(같은 소식)을 다룬 기사는 서로 다른 언론사가 각자 다른 제목·숫자 표기로 썼더라도(예: "2000억 달러"와 "292조원"은 같은 금액을 다르게 표기한 것) 반드시 같은 클러스터로 묶어라. 서로 관련 없는 별개의 사건은 각각 다른 클러스터로 남겨라.

각 클러스터를 아래 형식으로 한 줄씩 출력하라. 클러스터에 속한 인덱스를 쉼표로 나열한다(순서 무관, 1개짜리 클러스터도 반드시 한 줄로 출력하고, 모든 인덱스가 정확히 한 번씩만 등장해야 한다).
CLUSTER: <인덱스,인덱스,...>

다른 설명이나 마크다운, JSON은 출력하지 말고 CLUSTER: 로 시작하는 줄만 출력하라.

[기사 목록]
${listText}`;

return [{ json: { items, prompt } }];

const prep = $('T4. Code - 후보 정리(주가 제외+완전중복 제거) + AI 클러스터링 프롬프트 생성').first().json;
const items = prep.items || [];
const raw = String($json.text || $json.output || $json.response || $json.content || $json.result || '').trim();

const seen = new Set();
const clusters = [];
for (const line of raw.split(/\r?\n/)) {
  const m = line.match(/CLUSTER:\s*([\d,\s]+)/i);
  if (!m) continue;
  const idxs = m[1].split(',')
    .map(s => parseInt(s.trim(), 10))
    .filter(n => Number.isInteger(n) && n >= 0 && n < items.length && !seen.has(n));
  if (!idxs.length) continue;
  idxs.forEach(n => seen.add(n));
  clusters.push(idxs);
}
// AI 응답 파싱에 실패했거나 AI가 빠뜨린 기사는 각자 단독 클러스터로 보정한다.
items.forEach((_, i) => { if (!seen.has(i)) clusters.push([i]); });

function toIso(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

const deduped = clusters
  .map(idxs => ({ repIdx: Math.min(...idxs), memberCount: idxs.length }))
  .sort((a, b) => a.repIdx - b.repIdx)
  .slice(0, 5)
  .map(({ repIdx, memberCount }) => {
    const rep = items[repIdx];
    return {
      title: rep.title,
      url: rep.url,
      source: memberCount > 1 ? `${rep.source} 외 ${memberCount - 1}곳` : rep.source,
      published_at: toIso(rep.published_at_raw),
      summary: rep.summary,
      image_url: rep.image_url || null
    };
  });

if (!deduped.length) {
  throw new Error('AI 클러스터링 결과 저장할 기사가 없습니다. AI 응답: ' + raw.slice(0, 500));
}

return [{ json: { articles: deduped } }];
